/*
 * WebExtension Browser API Polyfill
 * This provides cross-browser compatibility between Chrome (chrome.*) and Firefox (browser.*)
 * Ensures promise-based APIs work consistently across both platforms
 */

(function () {
    'use strict';

    if (typeof globalThis === 'undefined') {
        // Polyfill for globalThis
        if (typeof self !== 'undefined') { self.globalThis = self; }
        else if (typeof window !== 'undefined') { window.globalThis = window; }
        else if (typeof global !== 'undefined') { global.globalThis = global; }
        else { throw new Error('Unable to locate global object'); }
    }

    // If browser API already exists (Firefox), we're good
    if (globalThis.browser && globalThis.browser.runtime && globalThis.browser.runtime.id) {
        return;
    }

    // Chrome polyfill: wrap chrome.* APIs to provide promise-based browser.* APIs
    const chrome = globalThis.chrome;

    if (!chrome) {
        throw new Error('Browser not supported: chrome or browser API required');
    }

    const browser = {};

    // Utility function to promisify chrome APIs
    function promisify(fn, context) {
        return function (...args) {
            return new Promise((resolve, reject) => {
                const callback = (result) => {
                    if (chrome.runtime.lastError) {
                        reject(chrome.runtime.lastError);
                    } else {
                        resolve(result);
                    }
                };

                try {
                    fn.call(context, ...args, callback);
                } catch (error) {
                    reject(error);
                }
            });
        };
    }

    // Runtime API
    browser.runtime = {
        id: chrome.runtime.id,

        sendMessage: chrome.runtime.sendMessage
            ? promisify(chrome.runtime.sendMessage, chrome.runtime)
            : undefined,

        onMessage: chrome.runtime.onMessage,
        onInstalled: chrome.runtime.onInstalled,
        onStartup: chrome.runtime.onStartup,

        getURL: chrome.runtime.getURL,
        getManifest: chrome.runtime.getManifest,

        connect: chrome.runtime.connect
            ? (...args) => chrome.runtime.connect(...args)
            : undefined
    };

    // Storage API
    browser.storage = {};

    if (chrome.storage) {
        ['local', 'sync', 'managed'].forEach(area => {
            if (chrome.storage[area]) {
                browser.storage[area] = {
                    get: promisify(chrome.storage[area].get, chrome.storage[area]),
                    set: promisify(chrome.storage[area].set, chrome.storage[area]),
                    remove: promisify(chrome.storage[area].remove, chrome.storage[area]),
                    clear: promisify(chrome.storage[area].clear, chrome.storage[area]),
                    onChanged: chrome.storage.onChanged
                };
            }
        });

        browser.storage.onChanged = chrome.storage.onChanged;
    }

    // Tabs API
    browser.tabs = {};

    if (chrome.tabs) {
        browser.tabs = {
            query: promisify(chrome.tabs.query, chrome.tabs),
            create: promisify(chrome.tabs.create, chrome.tabs),
            update: promisify(chrome.tabs.update, chrome.tabs),
            remove: promisify(chrome.tabs.remove, chrome.tabs),

            sendMessage: chrome.tabs.sendMessage
                ? promisify(chrome.tabs.sendMessage, chrome.tabs)
                : undefined,

            onActivated: chrome.tabs.onActivated,
            onUpdated: chrome.tabs.onUpdated,
            onRemoved: chrome.tabs.onRemoved
        };
    }

    // Action API (MV3) / BrowserAction API (MV2)
    const actionAPI = chrome.action || chrome.browserAction;

    if (actionAPI) {
        browser.action = {
            setBadgeText: promisify(actionAPI.setBadgeText, actionAPI),
            setBadgeBackgroundColor: promisify(actionAPI.setBadgeBackgroundColor, actionAPI),
            setTitle: promisify(actionAPI.setTitle, actionAPI),
            setIcon: promisify(actionAPI.setIcon, actionAPI),

            onClicked: actionAPI.onClicked
        };

        // For backwards compatibility with MV2
        if (chrome.browserAction && !chrome.action) {
            browser.browserAction = browser.action;
        }
    }

    // Notifications API
    if (chrome.notifications) {
        browser.notifications = {
            create: promisify(chrome.notifications.create, chrome.notifications),
            update: promisify(chrome.notifications.update, chrome.notifications),
            clear: promisify(chrome.notifications.clear, chrome.notifications),
            getAll: promisify(chrome.notifications.getAll, chrome.notifications),

            onClicked: chrome.notifications.onClicked,
            onClosed: chrome.notifications.onClosed,
            onButtonClicked: chrome.notifications.onButtonClicked
        };
    }

    // Scripting API (MV3)
    if (chrome.scripting) {
        browser.scripting = {
            executeScript: promisify(chrome.scripting.executeScript, chrome.scripting),
            insertCSS: promisify(chrome.scripting.insertCSS, chrome.scripting),
            removeCSS: promisify(chrome.scripting.removeCSS, chrome.scripting)
        };
    }

    // Context Menus API
    if (chrome.contextMenus) {
        browser.contextMenus = {
            create: promisify(chrome.contextMenus.create, chrome.contextMenus),
            update: promisify(chrome.contextMenus.update, chrome.contextMenus),
            remove: promisify(chrome.contextMenus.remove, chrome.contextMenus),
            removeAll: promisify(chrome.contextMenus.removeAll, chrome.contextMenus),

            onClicked: chrome.contextMenus.onClicked
        };

        // Alias for Firefox compatibility
        browser.menus = browser.contextMenus;
    }

    // Alarms API
    if (chrome.alarms) {
        browser.alarms = {
            create: chrome.alarms.create.bind(chrome.alarms),
            get: promisify(chrome.alarms.get, chrome.alarms),
            getAll: promisify(chrome.alarms.getAll, chrome.alarms),
            clear: promisify(chrome.alarms.clear, chrome.alarms),
            clearAll: promisify(chrome.alarms.clearAll, chrome.alarms),

            onAlarm: chrome.alarms.onAlarm
        };
    }

    // Windows API
    if (chrome.windows) {
        browser.windows = {
            get: promisify(chrome.windows.get, chrome.windows),
            getCurrent: promisify(chrome.windows.getCurrent, chrome.windows),
            getAll: promisify(chrome.windows.getAll, chrome.windows),
            create: promisify(chrome.windows.create, chrome.windows),
            update: promisify(chrome.windows.update, chrome.windows),
            remove: promisify(chrome.windows.remove, chrome.windows),

            onCreated: chrome.windows.onCreated,
            onRemoved: chrome.windows.onRemoved,
            onFocusChanged: chrome.windows.onFocusChanged
        };
    }

    // Expose the browser API globally
    globalThis.browser = browser;

    // Also keep chrome API for compatibility
    globalThis.chrome = chrome;

    console.log('🔧 WebExtension polyfill loaded - Chrome APIs wrapped with promises');
})();
